package com.example.campusmaintenance.service;
import com.example.campusmaintenance.dto.MaintenanceRequestDto; import com.example.campusmaintenance.entity.MaintenanceRequest; import com.example.campusmaintenance.enums.RequestStatus; import com.example.campusmaintenance.exception.ResourceNotFoundException; import com.example.campusmaintenance.repository.MaintenanceRequestRepository; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.List;
@Service public class MaintenanceRequestService {private static final Logger log=LoggerFactory.getLogger(MaintenanceRequestService.class); private final MaintenanceRequestRepository repo; public MaintenanceRequestService(MaintenanceRequestRepository r){repo=r;} public List<MaintenanceRequest> all(){return repo.findAll();} public MaintenanceRequest one(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Maintenance request with id "+id+" was not found"));} public MaintenanceRequest create(MaintenanceRequestDto d){MaintenanceRequest r=new MaintenanceRequest(); map(d,r);r.setStatus(RequestStatus.OPEN);r.setCreatedAt(LocalDateTime.now());r.setUpdatedAt(LocalDateTime.now());var s=repo.save(r);log.info("Created maintenance request id={}",s.getId());return s;} public MaintenanceRequest update(Long id,MaintenanceRequestDto d){var r=one(id);map(d,r);r.setUpdatedAt(LocalDateTime.now());return repo.save(r);} public MaintenanceRequest status(Long id,RequestStatus s){var r=one(id);r.setStatus(s);r.setUpdatedAt(LocalDateTime.now());return repo.save(r);} public void delete(Long id){repo.delete(one(id));} private void map(MaintenanceRequestDto d,MaintenanceRequest r){r.setTitle(d.getTitle());r.setDescription(d.getDescription());r.setCategory(d.getCategory());r.setPriority(d.getPriority());r.setStudentName(d.getStudentName());r.setRoom(d.getRoom());}}
